<script>
(function(){
  'use strict';
  var STORAGE_KEY = 'csp_registered_users_v1';
  var form = document.getElementById('registerForm');
  var status = document.getElementById('formStatus');
  var fields = {
    username: document.getElementById('username'),
    email: document.getElementById('email'),
    dob: document.getElementById('dob'),
    country: document.getElementById('country'),
    password: document.getElementById('password'),
    confirm: document.getElementById('confirm'),
    terms: document.getElementById('terms')
  };
  var errors = {
    username: document.getElementById('usernameError'),
    email: document.getElementById('emailError'),
    dob: document.getElementById('dobError'),
    password: document.getElementById('passwordError'),
    confirm: document.getElementById('confirmError'),
    terms: document.getElementById('termsError')
  };

  function loadUsers(){
    try{
      var raw = localStorage.getItem(STORAGE_KEY);
      if(!raw) return [];
      var data = JSON.parse(raw);
      return Array.isArray(data) ? data : [];
    }catch(e){ return []; }
  }
  function saveUsers(list){
    try{ localStorage.setItem(STORAGE_KEY, JSON.stringify(list)); }catch(e){}
  }
  function norm(s){ return (s || '').trim().toLowerCase(); }
  function findUser(username, email){
    var u = norm(username), e = norm(email);
    return loadUsers().some(function(r){ return r.u === u || r.e === e; });
  }

  var EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
  var USER_RE = /^[A-Za-z0-9_.\-]{3,30}$/;

  function setError(name, msg){
    var input = fields[name];
    var err = errors[name];
    if(err) err.textContent = msg || '';
    if(input && input.type !== 'checkbox'){
      if(msg){ input.classList.add('invalid'); input.setAttribute('aria-invalid','true'); }
      else{ input.classList.remove('invalid'); input.removeAttribute('aria-invalid'); }
    }
  }

  function validateField(name){
    var v = fields[name].value;
    switch(name){
      case 'username':
        if(!v.trim()) return 'Please choose a username.';
        if(!USER_RE.test(v.trim())) return 'Use 3–30 letters, digits, dots, underscores or hyphens.';
        if(findUser(v, fields.email.value)) return 'This username is already registered.';
        return '';
      case 'email':
        if(!v.trim()) return 'Please enter your email address.';
        if(v.length > 254) return 'Email address is too long.';
        if(!EMAIL_RE.test(v.trim())) return 'Enter a valid email address (e.g. name@example.com).';
        if(findUser(fields.username.value, v)) return 'An account with this email already exists.';
        return '';
      case 'dob':
        if(!v) return '';
        var d = new Date(v);
        if(isNaN(d.getTime())) return 'Enter a valid date.';
        var today = new Date(); today.setHours(0,0,0,0);
        if(d > today) return 'Date of birth cannot be in the future.';
        var min = new Date(); min.setFullYear(today.getFullYear() - 120);
        if(d < min) return 'Please enter a realistic date of birth.';
        return '';
      case 'password':
        if(!v) return 'Please choose a password.';
        if(v.length < 8) return 'Password must be at least 8 characters.';
        if(v.length > 128) return 'Password is too long.';
        if(!/[A-Za-z]/.test(v) || !/\d/.test(v)) return 'Use both letters and numbers.';
        return '';
      case 'confirm':
        if(!v) return 'Please re-enter your password.';
        if(v !== fields.password.value) return 'Passwords do not match.';
        return '';
      case 'terms':
        if(!fields.terms.checked) return 'You must accept the Terms of Service to continue.';
        return '';
    }
    return '';
  }

  function validateAll(){
    var names = ['username','email','dob','password','confirm','terms'];
    var firstInvalid = null;
    var ok = true;
    names.forEach(function(n){
      var msg = validateField(n);
      setError(n, msg);
      if(msg && !firstInvalid) firstInvalid = fields[n];
      if(msg) ok = false;
    });
    return { ok: ok, first: firstInvalid };
  }

  Object.keys(fields).forEach(function(name){
    var el = fields[name];
    if(!el) return;
    var ev = (el.type === 'checkbox') ? 'change' : 'input';
    el.addEventListener(ev, function(){
      if(errors[name]){
        var msg = validateField(name);
        setError(name, msg);
      }
    });
    if(el.type !== 'checkbox'){
      el.addEventListener('blur', function(){
        var msg = validateField(name);
        setError(name, msg);
      });
    }
  });

  document.querySelectorAll('.toggle-pw').forEach(function(btn){
    btn.addEventListener('click', function(){
      var id = btn.getAttribute('data-target');
      var input = document.getElementById(id);
      if(!input) return;
      var showing = input.type === 'text';
      input.type = showing ? 'password' : 'text';
      btn.setAttribute('aria-pressed', showing ? 'false' : 'true');
      btn.setAttribute('aria-label', showing ? (id === 'confirm' ? 'Show confirm password' : 'Show password') : (id === 'confirm' ? 'Hide confirm password' : 'Hide password'));
      btn.textContent = showing ? 'Show' : 'Hide';
      input.focus();
    });
  });

  status.classList.remove('success','error');

  form.addEventListener('submit', function(e){
    e.preventDefault();
    status.classList.remove('success','error');
    status.style.display = 'none';
    var result = validateAll();
    if(!result.ok){
      status.textContent = 'Please correct the highlighted fields and try again.';
      status.classList.add('error');
      status.style.display = 'block';
      if(result.first && typeof result.first.focus === 'function') result.first.focus();
      return;
    }
    var users = loadUsers();
    users.push({
      u: norm(fields.username.value),
      e: norm(fields.email.value),
      d: fields.dob.value || '',
      c: fields.country.value.trim(),
      t: Date.now()
    });
    saveUsers(users);

    status.textContent = 'Welcome, ' + fields.username.value.trim() + '! Your account has been created.';
    status.classList.add('success');
    status.style.display = 'block';
    form.reset();
    Object.keys(errors).forEach(function(k){ setError(k, ''); });
    fields.username.focus();
  });
})();
</script>
</body>
</html>
